//! 🧪️ Field close start uses the real original Work and caller receipt.
use semio_framework_replication_retained_field_preparation::RetainedFieldPreparation;
use semio_framework_value_retained_clone::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations;
struct Close;
impl OriginalEffectProducer for Close{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=&'a mut RetainedFieldPreparation<u64> where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.close_into(4096,effect,reply)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.recover_close_into(4096,effect,reply)}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn field_close_start_retains_original_funding(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../🧪️tests/🧫️fixtures/🛑️start.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:64,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:2};let mut bank=EffectBank::new(Wallet::new(stock,8));let mut field=RetainedFieldPreparation::<u64>::default();let demand=field.begin_close_demand();assert_eq!(demand.copy_bytes,law["flagBytes"].as_u64().unwrap()as usize);let permitted=grant(demand);let denied=RetainedCloneGrant{maximum_copy_bytes:0,..permitted};for selected in [denied,permitted]{let((poll,actual),heap)=observe_retirement_allocations(||bank.run(selected,1,|effect|RetainedWorkPoll::Complete(field.begin_close_paid(effect))));assert_eq!(actual,None);assert_eq!(heap,(0,0));let RetainedWorkPoll::Complete(turn)=poll else{panic!("field start pending")};let progress=turn.result.unwrap();if selected.maximum_copy_bytes==0{assert_eq!(turn.work,u128::from(law["denied"]["work"].as_u64().unwrap()));assert_eq!(field.close_started(),law["denied"]["started"].as_bool().unwrap());assert_eq!(progress.copied_bytes,law["denied"]["copy"].as_u64().unwrap()as usize);assert_eq!(progress,RetainedCloneProgress::default())}else{assert_eq!(turn.work,u128::from(law["admitted"]["work"].as_u64().unwrap()));assert_eq!(field.close_started(),law["admitted"]["started"].as_bool().unwrap());assert_eq!(progress.copied_bytes,law["admitted"]["copy"].as_u64().unwrap()as usize)}assert_ne!(bank.take_admitted(),Some(false));bank.post(progress,selected,heap);}
 let demand=field.close_demand(4096).unwrap();let work=field.close_work_demand(4096).unwrap();let selected=grant(demand);let mut authority=OriginalEffectAuthority::new(Close);let mut action=None;let mut output=None;let((poll,actual),heap)=observe_retirement_allocations(||bank.run(selected,work,|effect|{let before=effect.performed_work();let mut context=&mut field;let ready=authority.drive(&mut context,effect,&mut action).unwrap();let actual=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:actual})}else{RetainedWorkPoll::Pending{work:actual}}}));assert_eq!(actual,None);assert_eq!(heap,(0,0));assert!(matches!(poll,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert!(action.as_mut().unwrap().transfer_reply(&mut output).unwrap());authority.finish(&mut action).unwrap();let step=output.take().unwrap().unwrap();assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),selected,heap);assert!(field.terminal_is_empty());assert!(authority.into_producer().is_ok());}
